            bc = parse_cost(raw_op["bc"])
            cc = parse_cost(raw_op["cc"])
            sc = parse_cost(raw_op["sc"])
            if bc == 0 and cc == 0 and sc == 0:
                # 三项成本全零非法。
                fail(EXIT_INPUT, "INPUT")
        else:
            fail(EXIT_INPUT, "INPUT")
        return (
            "la",
            parse_key(raw_op["c"]),
            parse_key(raw_op["s"]),
            parse_key(raw_op["key"]),
            bc,
            cc,
            sc,
            parse_now(raw_op["now"]),
        )

    if name == "lg":
        if keys != {"op", "scope", "id", "now"}:
            fail(EXIT_INPUT, "INPUT")
        scope = raw_op["scope"]
        if scope not in ("B", "C", "S"):
            fail(EXIT_INPUT, "INPUT")
        return (
            "lg",
            scope,
            parse_key(raw_op["id"]),
            parse_now(raw_op["now"]),
