                ttl_cfg = ttl
            elif ttl_cfg != ttl:
                # 异值重配报 STATE；同值幂等。
                fail(EXIT_STATE, "STATE")
            results.append({"op": "ts", "ok": True})

        elif op[0] == "tk":
            _, cid, now = op
